import hashlib
import os

def get_file_hash(filepath):
    hasher = hashlib.sha256()
    try:
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):
                hasher.update(chunk)
        return hasher.hexdigest()
    except Exception:
        return None

def find_duplicates(root_dir):
    hashes = {}
    for root, dirs, files in os.walk(root_dir):
        for filename in files:
            filepath = os.path.join(root, filename)
            file_hash = get_file_hash(filepath)
            if file_hash is not None:
                # Get relative path with forward slashes as requested
                rel_path = os.path.relpath(filepath, root_dir).replace('\\', '/')
                if file_hash in hashes:
                    hashes[file_hash].append(rel_path)
                else:
                    hashes[file_hash] = [rel_path]

    # Filter groups with at least 2 files and sort them
    duplicate_groups = []
    for group in hashes.values():
        if len(group) >= 2:
            group.sort() # Sort paths within the group alphabetically
            duplicate_groups.append(group)

    # Sort groups by their first file's path
    duplicate_groups.sort(key=lambda x: x[0])
    return duplicate_groups

root = 'dosyalar'
if not os.path.exists(root):
    print(f"Error: {root} directory not found.")
else:
    duplicates = find_duplicates(root)
    with open('kopyalar.txt', 'w', encoding='utf-8') as f:
        for group in duplicates:
            f.write(" | ".join(group) + "\n")
    print(f"Found {len(duplicates)} duplicate groups. Results written to kopyalar.txt.")

